def copy_stock_into_warehouse(apps, schema_editor):
    Product = apps.get_model('products', 'Product')
    ProductVariant = apps.get_model('products', 'ProductVariant')
    for product in Product.objects.all().only('id', 'stock_quantity'):
        Product.objects.filter(pk=product.pk).update(
            warehouse_stock=product.stock_quantity or 0,
            dealer_stock=0,
        )
    for variant in ProductVariant.objects.all().only('id', 'stock_quantity'):
        ProductVariant.objects.filter(pk=variant.pk).update(
            warehouse_stock=variant.stock_quantity or 0,
            dealer_stock=0,
        )


def publish_all_products(apps, schema_editor):
    Product = apps.get_model('products', 'Product')
    Product.objects.filter(is_active=False).update(is_active=True)


